  (* [comment removed for export] *)
  Lemma fsobj_windows : forall LF O n k ff fp m,
    as_RFS H LF m -> fsobj LF O n -> fresh_frame LF k ff fp -> 0 <= O -> 0 <= n -> O + n <= AAPP_HI ->
       (O + n <= ff \/ ff + fsz k <= O)
    /\ (sh O + nsh n <= sh ff \/ sh ff + fshn k <= sh O)
    /\ (O + n <= fp \/ fp + 1 <= O)
